function Get-PerformanceBaseline { [CmdletBinding()]param();$o=Get-CimInstance Win32_OperatingSystem;$used=$o.TotalVisibleMemorySize-$o.FreePhysicalMemory;[pscustomobject]@{Timestamp=(Get-Date).ToString('o');CpuPercent=(Get-CimInstance Win32_Processor|Measure-Object LoadPercentage -Average).Average;TotalMemoryGB=[math]::Round($o.TotalVisibleMemorySize/1MB,2);AvailableMemoryGB=[math]::Round($o.FreePhysicalMemory/1MB,2);MemoryUsedPercent=[math]::Round(100*$used/$o.TotalVisibleMemorySize,2);TopProcesses=@(Get-Process|Sort-Object WorkingSet64 -Descending|Select-Object -First 15 Name,Id,@{n='MemoryMB';e={[math]::Round($_.WorkingSet64/1MB,2)}})} }